package com.example.restaurant.controller;
import com.example.restaurant.dto.SalesNotificationResponse; import com.example.restaurant.service.SalesMilestoneService; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/api/notifications") @SecurityRequirement(name="basicAuth") @Tag(name="Notifications")
public class NotificationController {private final SalesMilestoneService service; public NotificationController(SalesMilestoneService service){this.service=service;} @GetMapping public List<SalesNotificationResponse> list(@RequestParam(defaultValue="0") long afterId){return service.notificationsAfter(LocalDate.now(),afterId);}}
